  ui_story_40110001_12_dialog_content = "Baiklah...",
  ui_story_40110001_13_dialog_content = "Seorang pilot Colossus master dengan pengalaman setidaknya 17 tahun, ia juga memiliki kekuatan untuk membaca pikiran orang! Seorang anak ajaib, tentunya, atau mungkin semacam monster...",
  ui_story_40110001_14_dialog_content = "A-apa? Tidak! Aku tidak bisa mengemudikan Colossus HINGGA aku berusia 17 tahun! Selain itu, aku juga tidak bisa membaca pikiran!",
