  ui_story_40110001_23_dialog_content = "M-maaf, aku sedikit bersemangat. Seharusnya aku tidak terlalu cepat mencurigai kalian...",
  ui_story_40110001_24_dialog_content = "Meski kami menulis perkenalan itu...",
