  ui_story_40110001_56_dialog_content = "\"Dan menatap melalui air di dalamnya.\"",
  ui_story_40110001_57_dialog_content = "\"Terkenang hari-hari yang kita habiskan bersama...\"",
  ui_story_40110001_58_dialog_content = "\"Namun, perasaan mengancam untuk memecah belah diriku.\"",
  ui_story_40110001_59_dialog_content = "\"Kamu telah pergi ke suatu tempat yang jauh sekali...\"",
  ui_story_40110001_60_dialog_content = "\"Dan bumi yang senyap menahan rasa gembiraku...\"",
  ui_story_40110001_61_dialog_content = "\"Satu-satunya asaku adalah melihatmu satu kali lagi,\"",
