  ui_story_40110001_70_dialog_content = "Dia hanya mengabaikanku saat ini, 'kan...",
  ui_story_40110001_71_dialog_content = "Silakan bagikan...",
  ui_story_40110001_72_dialog_content = "Iya, iya, aku paham! Astaga!",
  ui_story_40110001_73_option_content = "Aku rasa cukup bagus...",
  ui_story_40110001_74_dialog_content = "Setidaknya, itu jauh lebih baik ketimbang hal-hal yang biasanya kamu katakan tentang diriku atau rambutku.",
  ui_story_40110001_75_dialog_content = "Aku tahu kalian mempermainkanku, tetapi bagian \"rumput liar di luar pintumu\" sebenarnya cukup puitis.",
  ui_story_40110001_76_option_content = "Itu sangat buruk...",
  ui_story_40110001_77_dialog_content = "Yang bisa kupikirkan setelah menyimak puisimu adalah, \"Entah apa yang mereka bicarakan...\"",
  ui_story_40110001_78_dialog_content = "Maksudku, gayanya tidak konsisten, kata-katanya terlalu sederhana, dan makna di baliknya... tidak jelas.",
  ui_story_40110001_79_dialog_content = "Apa Uriah mengajari kalian cara baru untuk mempermainkanku atau semacamnya?",
  ui_story_40110001_80_dialog_content = "PlayerName tersayang,",
  ui_story_40110001_81_dialog_content = "Gayanya mungkin tidak konsisten...",
  ui_story_40110001_82_dialog_content = "Namun, perasaan kami sudah jelas.",
  ui_story_40110001_83_dialog_content = "Namun, tidak hanya kamu tidak bisa memahami puisi kami...",
  ui_story_40110001_84_dialog_content = "Kamu juga punya nyali untuk mengkritiknya.",
  ui_story_40110001_85_dialog_content = "Kalian yang memintaku untuk menilai sejak awal!!!",
  ui_story_40110001_86_dialog_content = "Eh, t-tolong jangan marah. Kamu mau air putih?",
  ui_story_40110001_87_dialog_content = "Tidak, terima kasih, aku tidak benar-benar marah. Aku hanya sedikit bersemangat, itu saja.",
  ui_story_40110001_88_dialog_content = "Luar biasa! Kalau begitu, kamu mau manisan? Semua orang merasa lebih baik setelah memakan sesuatu yang manis...",
  ui_story_40110001_89_dialog_content = "T-tidak juga, aku sama sekali tidak marah... Sumpah...",
  ui_story_40110001_90_dialog_content = "Sekarang, izinkan aku menyampaikan kepadamu...",
  ui_story_40110001_91_dialog_content = "Belasungkawa kami yang paling tulus.",
  ui_story_40110001_92_dialog_content = "Hari ini, kami ingin mengenang teman tersayang kami.",
  ui_story_40110001_93_dialog_content = "T-tunggu sebentar! Kamu yakin ini masih untukku?!",
  ui_story_40110001_94_dialog_content = "Ya.",
  ui_story_40110001_95_dialog_content = "Maaf, aku sungguh tidak tahu harus berkata apa...",
  ui_story_40110001_96_dialog_content = "Jangan khawatir. Tidak apa-apa jika kamu ingin duduk merenung dengan tenang setelah mendengar puisi berikut ini.",
  ui_story_40110001_97_dialog_content = "T-tidak, hanya saja... Apakah seharusnya aku mati?",
  ui_story_40110001_98_dialog_content = "Jelas. Lagi pula, bagian dari pekerjaanku adalah memimpin pemakaman.",
  ui_story_40110001_99_dialog_content = "Jadi, agar lebih jelas... Kenapa kita mengadakan kontes puisi hari ini?",
  ui_story_40110001_100_dialog_content = "Ini adalah latihan untuk resital puisi! Juga untuk melihat reaksimu.",
  ui_story_40110001_101_dialog_content = "Reaksiku? Tunggu, kalian berlatih untuk pemakamanku?!",
  ui_story_40110001_102_dialog_content = "... Ini adalah latihan untuk resital puisi!",
  ui_story_40110001_103_dialog_content = "Kamu mengabaikanku lagi! Selain itu...",
  ui_story_40110001_104_dialog_content = "Apakah dia menangis di sana?!",
  ui_story_40110001_105_dialog_content = "*Hiks* Maafkan aku... Hanya saja, ketika aku memikirkanmu... Aku...",
  ui_story_40110001_106_dialog_content = "Hentikan itu, aku benar-benar belum mati!",
  ui_story_40110001_107_dialog_content = "Aku minta maaf, tetapi karena gangguan yang tidak terduga, kontes hari ini sedikit tertunda.",
  ui_story_40110001_108_dialog_content = "Tanpa perlu berbasa-basi lagi, mari kita lanjutkan sekali lagi!",
  ui_story_40110001_109_dialog_content = "Karena kekhawatiran bahwa gangguan ini akan memengaruhi performa kontestan ketiga, ada sedikit penyesuaian dalam urutannya. Mari kita sambut Chloe, silakan naik ke panggung!",
  ui_story_40110001_110_dialog_content = "Chloe, kamu...",
  ui_story_40110001_111_dialog_content = "S-semuanya baik-baik saja? Kamu masih mau lanjut...?",
  ui_story_40110001_112_dialog_content = "Anu, aku... Tunggu, bukankah seharusnya aku yang menanyakan itu padamu?!",
  ui_story_40110001_113_dialog_content = "Yah, hanya saja... Mengingat situasi pikiranmu saat ini...",
  ui_story_40110001_114_dialog_content = "Aku baik-baik saja, sumpah!! Lagi pula, kamu yakin kamu baik-baik saja? Semenit lalu kamu menangis!",
  ui_story_40110001_115_dialog_content = "T-tidak apa-apa... Aku bisa melakukan ini...",
  ui_story_40110001_116_dialog_content = "Begitulah biasanya orang...",
  ui_story_40110001_117_dialog_content = "\"Memang begitulah aku!\"",
  ui_story_40110001_118_dialog_content = "(Kenapa dia tiba-tiba bernyanyi?! Lumayan juga...)",
  ui_story_40110001_119_dialog_content = "\"Aku tahu, tentu aku tahu, kita harus beranjak! Namun, kenangan kita tidaklah mudah berlalu!\"",
  ui_story_40110001_120_dialog_content = "\"Mungkin kebahagiaan kita telah terkutuk sejak awal...\"",
  ui_story_40110001_121_dialog_content = "\"Namun, dunia tidak peduli, karena ia terus berputar...\"",
  ui_story_40110001_122_dialog_content = "Aku...",
  ui_story_40110001_123_dialog_content = "Oh, Chloe, kamu menangis lagi...",
  ui_story_40110001_124_dialog_content = "Wow, bahkan kita tidak akan bisa membuatnya menangis seperti ini...",
  ui_story_40110001_125_dialog_content = "Kamu memang luar biasa, Navigator.",
  ui_story_40110001_126_dialog_content = "Kuharap kamu bangga pada dirimu sendiri.",
  ui_story_40110001_127_dialog_content = "A-apa?! Mengapa kalian menatapku? Aku tidak melakukan apa-apa!!",
  ui_story_40110001_128_dialog_content = "Maaf... Hanya saja, saat memikirkanmu... Aku...",
  ui_story_40110001_129_dialog_content = "\"Saat kau memikirkanku\"? Kubilang aku baik-baik saja! Jangan menangis!",
  ui_story_40110001_130_dialog_content = "Aku kembali! Aku sudah menyelesaikan permintaanmu, Uriah!",
  ui_story_40110001_131_dialog_content = "Apa? Tunggu, Vice... Kamu pergi lebih awal karena Uriah memintamu melakukan sesuatu? Apa itu?!",
  ui_story_40110001_132_dialog_content = "Nah, Navigator, begini... Kita akan segera mendarat.",
  ui_story_40110001_133_dialog_content = "Mendarat? Di mana kita mendarat? Kenapa tidak ada yang memberitahuku?!",
  ui_story_40110001_134_dialog_content = "Di suatu tempat di pinggiran Umbraton... Sepertinya? Omong-omong, kita tidak bisa tetap di darat terlalu lama, atau kita bisa berada dalam masalah serius.",
  ui_story_40110001_135_dialog_content = "Hah?! A-apa yang terjadi di sini?!",
  ui_story_40110001_136_dialog_content = "Maaf, Navigator... Namun, resital paduan suara akan segera dimulai, dan waktu kita tak banyak.",
  ui_story_40110001_137_dialog_content = "Sebenarnya apa niatmu? Ke mana kita akan pergi? Seseorang harus segera memberitahuku!",
  ui_story_40110001_138_dialog_content = "Cepat, Navigator! Pegang bunga ini!",
  ui_story_40110001_139_dialog_content = "Hah? Dari mana kamu mendapatkan bunga putih ini?!",
  ui_story_40110001_140_dialog_content = "T-tunggu! Kalian mau pergi ke mana?!",
  ui_story_40110001_141_dialog_content = "*Berdesah*... Apakah aku benar-benar ingin mengikuti...?",
  ui_story_40110001_142_dialog_content = "Sedang apa kita di lapangan luas yang kosong ini? Tidak ada orang di sekitar sini... Tidak, tunggu, siapa orang-orang itu?",
  ui_story_40110001_143_dialog_content = "Kebanyakan dari mereka sepertinya berasal dari Umbraton... Tunggu dulu, ada orang Lumopolis juga?",
  ui_story_40110001_144_dialog_content = "Aku...",
  ui_story_40110001_145_option_content = "Sepertinya aku harus tinggal.",
  ui_story_40110001_146_dialog_content = "<color=#e8d9bb>Seseorang mendorong punggungku dengan lembut.</color>",
  ui_story_40110001_147_dialog_content = "Vice...",
  ui_story_40110001_148_dialog_content = "Silakan, serahkan Colossus padaku. Aku akan kembali untuk menjemputmu nanti.",
  ui_story_40110001_149_dialog_content = "Namun, aku masih belum paham apa yang terjadi! Kenapa aku harus pergi dengan mereka...?",
  ui_story_40110001_150_dialog_content = "... Lihat, mereka sudah begitu jauh di depan.",
  ui_story_40110001_151_dialog_content = "Baru saja, saat kontes puisi... Satu detik kamu tertawa, satu detik lagi kamu marah, tetapi kamu berbicara dan berinteraksi dengan semua orang sama saja.",
  ui_story_40110001_152_dialog_content = "Kali pertama aku melihatmu, aku tidak pernah menyangka kamu bisa menunjukkan emosi sebanyak ini.",
  ui_story_40110001_153_dialog_content = "Seperti yang Keating bilang: Semua orang mengagumimu lebih dari yang kamu tahu, sekarang pergilah!",
  ui_story_40110001_154_dialog_content = "Namun...",
  ui_story_40110001_155_dialog_content = "Semua orang menunggu bunga di tanganmu, jadi jangan biarkan mereka menunggu terlalu lama.",
  ui_story_40110001_156_dialog_content = "... Baiklah. Kalau begitu, aku akan pergi.",
  ui_story_40110001_157_option_content = "Aku harus menyusul mereka.",
  ui_story_40110001_158_dialog_content = "Mereka berjalan terlalu cepat! Tidak bisakah mereka melihat aku membawa karangan bunga sebesar ini...?",
  ui_story_40110001_159_dialog_content = "...",
  ui_story_40110001_160_dialog_content = "Kenapa ada penjaga bersenjata tiba-tiba bergegas ke arahku?!",
  ui_story_40110001_161_dialog_content = "Berhenti!",
  ui_story_40110001_162_dialog_content = "*Ehem* A-ada masalah apa? Begini, aku diundang ke sini oleh orang-orang penting di Lumopolis...",
  ui_story_40110001_163_dialog_content = "Lihat kerumunan berpakaian serbaputih di sana? Aku bersama mereka.",
  ui_story_40110001_164_dialog_content = "Jika kamu tidak percaya, tanyakan pada salah satu dari mereka! Namun, kumohon, letakkan saja senjatamu!",
  ui_story_40110001_165_dialog_content = "Kamu... Kenapa kamu begitu takut?",
  ui_story_40110001_166_dialog_content = "S-siapa yang takut? A-aku benar-benar tenang!",
  ui_story_40110001_167_dialog_content = "Kamu sangat gemetar sampai-sampai semua bungamu jatuh...",
  ui_story_40110001_168_dialog_content = "A-ah, itu karena aku terlalu banyak membawanya!",
  ui_story_40110001_169_dialog_content = "Begitu, ya. Biarkan aku membantumu memungutnya.",
  ui_story_40110001_170_dialog_content = "Eh? Ba-baiklah... Terima kasih.",
  ui_story_40110001_171_dialog_content = "<color=#e8d9bb>Penjaga itu memungut seikat besar bunga sebelum berlari ke arah sekelompok besar orang.</color>",
  ui_story_40110001_172_dialog_content = "<color=#e8d9bb>Uriah berdiri di tengah kerumunan, tampaknya ia sedang bicara dengan orang-orang di sekitarnya...</color>",
  ui_story_40110001_173_dialog_content = "Terima kasih telah datang ke resital puisi kami hari ini.",
  ui_story_40110001_174_dialog_content = "Hari ini, kami ingin mengungkapkan kesedihan dan dukacita kami yang paling dalam.",
  ui_story_40110001_175_dialog_content = "Hari ini, kami ingin mengenang teman tersayang kami.",
  ui_story_40110001_176_dialog_content = "Untuk teman kami.",
  ui_story_40110001_177_dialog_content = "Pada suatu hari, negeri ini dilanda perang besar yang membinasakannya, banyak yang gugur akibat ancaman Eclipsite...",
  ui_story_40110001_178_dialog_content = "Ada yang menganggap mereka sebagai musuh, ada juga yang menganggapnya sebagai kekuatan alam yang buta dan menghancurkan...",
  ui_story_40110001_179_dialog_content = "<color=#e8d9bb>Setelah mengatakan hal tersebut, Uriah mulai membagikan bunga putih kepada setiap orang di kerumunan.</color>",
  ui_story_40110001_180_dialog_content = "<color=#e8d9bb>Kemudian Chloe mulai menyanyikan lagu, \"White Flower\".</color>",
  ui_story_40110001_181_dialog_content = "<color=#e8d9bb>Alih-alih menimbulkan masalah seperti biasa, Keating diam-diam menghibur tamu yang menangis.</color>",
  ui_story_40110001_182_dialog_content = "<color=#e8d9bb>Ini adalah pemakaman kecil, dan semua yang mereka lakukan sebelumnya adalah persiapan untuknya.</color>",
  ui_story_40110001_183_dialog_content = "Jadi, kontes puisi... diadakan untuk memilih puisi mana yang akan dibacakan di sini...",
  ui_story_40110001_184_dialog_content = "Aku masih belum yakin apa ide di balik kontes itu sebenarnya...",
  ui_story_40110001_185_option_content = "Tanyakan pada Uriah.",
  ui_story_40110001_186_dialog_content = "Navigator, kamu ingat bunga putih yang kuberikan sebelumnya?",
  ui_story_40110001_187_dialog_content = "Ya.",
  ui_story_40110001_188_dialog_content = "Hari itu, kamu memintaku mengisahkan ceritaku, tetapi sebenarnya aku tidak punya cerita...",
  ui_story_40110001_189_dialog_content = "Dulu aku hanyalah orang biasa, orang yang bertahan hidup dengan meninggalkan garis depan.",
  ui_story_40110001_190_dialog_content = "Keluargaku, teman-temanku... Semuanya hidup dan baik-baik saja.",
  ui_story_40110001_191_dialog_content = "Seseorang pernah bertanya kepadaku, \"Apa yang mungkin kamu tahu soal rasa sakit akibat kehilangan seseorang?\"",
  ui_story_40110001_192_dialog_content = "Apakah itu saat pemakaman yang kamu pimpin?",
  ui_story_40110001_193_dialog_content = "Ya... Mungkin pendekatanku gagal untuk mempertimbangkan perasaanmu, dan untuk itu aku minta maaf.",
  ui_story_40110001_194_dialog_content = "Namun, saat Keating bilang dia ingin mengundangmu ke resital puisi, aku menyetujuinya dengan sepenuh hati.",
  ui_story_40110001_195_dialog_content = "Navigator... Terlepas dari air matanya yang terus mengalir, Chloe benar-benar berharap kamu lebih banyak tersenyum.",
  ui_story_40110001_196_dialog_content = "Vice setuju, itulah sebabnya dia memilih untuk membantu kami.",
  ui_story_40110001_197_dialog_content = "Ah... Sepertinya sekarang aku paham. Jadi, pada dasarnya, kamu berharap aku bisa menerima \"resital puisi\" ini, 'kan?",
  ui_story_40110001_198_dialog_content = "Ya. Aku memercayaimu... seperti orang lain, memiliki orang-orang yang ingin dikenang.",
  ui_story_40110001_199_dialog_content = "Namun, apa yang seharusnya aku lakukan? Jika aku memiliki orang yang ingin aku ingat...",
  ui_story_40110001_200_dialog_content = "Kamu bisa melakukan hal yang dilakukan orang lain dan meletakkan bunga di lapangan agar angin dapat membawanya.",
  ui_story_40110001_201_dialog_content = "Ya.",
  ui_story_40110001_202_option_content = "Tanyakan pada Chloe.",
  ui_story_40110001_203_dialog_content = "Kamu baik saja? Air matamu berlinang barusan... Apakah angin di sini membuat matamu pedih?",
  ui_story_40110001_204_dialog_content = "Aku baik-baik saja, terima kasih telah memedulikanku.",
  ui_story_40110001_205_dialog_content = "Resital puisi ini... Tidak seperti yang kuharapkan.",
  ui_story_40110001_206_dialog_content = "Ya... Tidak ada panggung megah, tidak ada cahaya yang berkedip...",
  ui_story_40110001_207_dialog_content = "Hanya tanah, rumput, dan angin di sekitar kita... Namun, meski begitu, mereka bersedia hadir.",
  ui_story_40110001_208_dialog_content = "\"Aku tahu, tentu aku tahu, kita harus beranjak! Namun, kenangan kita tidaklah mudah berlalu!\"",
  ui_story_40110001_209_dialog_content = "\"Mungkin kebahagiaan kita telah terkutuk sejak awal...\"",
  ui_story_40110001_210_dialog_content = "\"Namun, dunia tidak peduli, karena ia terus berputar...\"",
  ui_story_40110001_211_dialog_content = "\"Aku mendambakan berjalan-jalan di tepi danau yang jauh...\"",
  ui_story_40110001_212_dialog_content = "\"Dari burung-burung yang bernyanyi saat matahari terbenam...\"",
  ui_story_40110001_213_dialog_content = "\"Aku tahu, tentu aku tahu, kita harus beranjak! Namun, kenangan kita tidaklah mudah berlalu!\"",
  ui_story_40110001_214_dialog_content = "\"Apakah ingatan kita akan memudar dari lapangan itu atau dari hati kita?\"",
  ui_story_40110001_215_dialog_content = "\"Namun, masih begitu banyak rasa sakit yang belum pergi...\"",
  ui_story_40110001_216_dialog_content = "\"Yang bisa kulakukan hanyalah meletakkan kembang di dataran ini... Dan berharap angin membawanya pergi bersama rasa sakitku.\"",
  ui_story_40110001_217_option_content = "Tanyakan pada Keating.",
  ui_story_40110001_218_dialog_content = "Sepertinya Chloe sudah selesai bernyanyi.",
  ui_story_40110001_219_dialog_content = "Bagaimana menurutmu?",
  ui_story_40110001_220_dialog_content = "Hmm? Kenapa kamu tiba-tiba menanyakan itu?",
  ui_story_40110001_221_dialog_content = "Tampak kamu menikmatinya waktu di Colossus.",
  ui_story_40110001_222_dialog_content = "Lagunya mungkin lagu favoritmu, 'kan?",
  ui_story_40110001_223_dialog_content = "Hah? Oh, kamu masih bicara soal kontes puisi.",
  ui_story_40110001_224_dialog_content = "Aku pikir kamu hanya menggodaku lagi.",
  ui_story_40110001_225_dialog_content = "Masih belum yakin? Atau apakah kamu tidak mau memikirkannya saja?",
  ui_story_40110001_226_dialog_content = "Hentikan! Ini semua idemu, 'kan? Katakan padaku apa yang terjadi.",
  ui_story_40110001_227_dialog_content = "Tidak sebelum kamu memberi tahu kami lagu favoritmu!",
  ui_story_40110001_228_dialog_content = "Jangan coba-coba untuk menghindari pertanyaan.",
  ui_story_40110001_229_dialog_content = "Halo, PlayerName.",
  ui_story_40110001_230_dialog_content = "Mencari kebenaran itu biasa dan boleh-boleh saja,",
  ui_story_40110001_231_dialog_content = "Namun, pertama, kamu harus lulus dari uji pikiran.",
  ui_story_40110001_232_dialog_content = "Dan hanya dengan begitulah jawabannya akan menjadi milikmu.",
  ui_story_40110001_233_dialog_content = "\"Ada yang kehilangan kekasih mereka,\"",
  ui_story_40110001_234_dialog_content = "\"Ada yang kehilangan teman mereka.\"",
  ui_story_40110001_235_dialog_content = "\"Yang mereka inginkan hanyalah bertemu lagi dengan mereka,\"",
  ui_story_40110001_236_dialog_content = "Sekarang, menurutmu seperti apa baris selanjutnya?",
  ui_story_40110001_237_dialog_content = "\"Namun, yang kulihat hanyalah rumput liar di luar pintumu.\"",
  ui_story_40110001_238_dialog_content = "Maaf, kupikir akhirnya aku mengerti...",
  ui_story_40110001_239_dialog_content = "Kalian tidak sedang mengejek atau mencandai siapa pun... Kalian menyiapkan puisi-puisi ini dengan sepenuh hati.",
  ui_story_40110001_240_dialog_content = "Ya.",
  ui_story_40110001_241_dialog_content = "Halo, PlayerName.",
  ui_story_40110001_242_dialog_content = "Ini dia, kebenaran yang telah lama ditunggu!",
  ui_story_40110001_243_dialog_content = "Kamu benar-benar yakin ini semua untukmu?",
  ui_story_40110001_244_dialog_content = "Membiarkanmu berpartisipasi itu sebenarnya keputusan menit terakhir.",
  ui_story_40110001_245_dialog_content = "Dan kami hanya perlu tumpangan menuju tempat tersebut.",
  ui_story_40110001_246_dialog_content = "Kalian... Sepertinya Keating masih sama seperti sebelumnya...",
  ui_story_40110001_247_dialog_content = "<color=#e8d9bb>Angin tiba-tiba berembus, meniup mereka saat kerumunan itu saling berangkulan.</color>",
  ui_story_40110001_248_dialog_content = "Sepertinya Vice datang menjemput kita. Kita kembali bersama, yuk?",
  ui_story_40110001_249_dialog_content = "Bagaimana denganmu?",
  ui_story_40110001_250_dialog_content = "Tentu saja.",
  ui_story_40110001_251_dialog_content = "Ya... Bersama-sama."
}
return config
